/**
 * Generated files: derived from the repository, never edited by hand. `aiv check` fails when one
 * is stale; `aiv check --fix` rewrites them. Whole files (schemas, catalog.json, docs/INDEX.md),
 * marked blocks inside hand-written docs (`<!-- aiv:generated <name> -->` … `<!-- /aiv:generated -->`),
 * and the `exclude` list of tsconfig.json (frozen videos leave the typecheck).
 *
 * Output is a pure function of the repository: no dates, no absolute paths, stable order.
 */
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { ReleaseManifest, RenderResult } from '@aiv/core';
import { z } from 'zod';
import { gatesTable } from './gates.ts';
import { mdSummary, mdTitle } from './md.ts';
import { importedPackages, type RepoModel } from './repo.ts';
import { isFrozen, SeriesConfig, VideoSlot, type VideoSlot as Slot } from './schema.ts';

export const REPO_URL = 'https://github.com/earthwalker17/AI-videos';
const GENERATED_NOTE = 'Generated by `pnpm aiv check --fix`; do not edit by hand.';

export interface Generated {
  /** repo-relative file */
  path: string;
  /** a marked block inside the file, or the whole file when absent */
  block?: string;
  /** the tsconfig exclude list is a JSON field, not text */
  jsonField?: string;
  content: string;
}

export type Freshness = 'fresh' | 'stale' | 'no-marker';

// ---- schemas -------------------------------------------------------------------------------

export const SCHEMAS = [
  { file: 'schemas/video.v1.json', title: 'video.json v1: one video slot', schema: VideoSlot },
  { file: 'schemas/series.v1.json', title: 'series.json v1', schema: SeriesConfig },
  { file: 'schemas/render.v1.json', title: 'render.json v1: what an engine hands to post', schema: RenderResult },
  { file: 'schemas/release.v1.json', title: 'release manifest v1 (videos/<slug>/release/v<N>.json)', schema: ReleaseManifest },
] as const;

const json = (v: unknown) => `${JSON.stringify(v, null, 2)}\n`;

export function schemaFile(s: (typeof SCHEMAS)[number]): string {
  const body = z.toJSONSchema(s.schema, { target: 'draft-2020-12', io: 'input' }) as Record<string, unknown>;
  delete body.$schema;
  return json({ $schema: 'https://json-schema.org/draft/2020-12/schema', $id: `${REPO_URL}/blob/main/${s.file}`, title: s.title, $comment: GENERATED_NOTE, ...body });
}

// ---- catalog -------------------------------------------------------------------------------

const videosOf = (m: RepoModel): { dir: string; v: Slot }[] =>
  m.videos.filter((l) => l.data).map((l) => ({ dir: l.dir, v: l.data! })).sort((a, b) => a.v.number - b.v.number);

const watch = (v: Slot) => (v.youtube ? `https://youtu.be/${v.youtube.id}` : null);

/** Code folders of frozen videos (src/ and the score's audio/): out of the typecheck and lint scope (decision 4). */
export const frozenSources = (m: RepoModel): string[] =>
  videosOf(m)
    .filter(({ v }) => isFrozen(v.status))
    .flatMap(({ dir }) => ['src', 'audio'].filter((f) => existsSync(join(m.root, dir, f))).map((f) => `${dir}/${f}`));

function catalog(m: RepoModel): string {
  const videos = videosOf(m);
  const usedBy = (pred: (v: Slot, dir: string) => boolean) => videos.filter(({ v, dir }) => pred(v, dir)).map(({ v }) => v.slug);
  return json({
    $comment: `${GENERATED_NOTE} The machine-readable index of this repository.`,
    schemaVersion: 1,
    videos: videos.map(({ dir, v }) => ({
      number: v.number,
      slug: v.slug,
      title: v.title,
      series: v.series,
      status: v.status,
      engine: v.engine ?? null,
      reproducibility: v.reproducibility,
      languages: v.languages,
      path: dir,
      watch: watch(v),
      reusable: v.reusable.map((x) => ({ path: `${dir}/${x.path}`, what: x.what })),
    })),
    series: m.series
      .filter((s) => s.data)
      .map((s) => ({ id: s.data!.id, title: s.data!.title, status: s.data!.status, summary: s.data!.summary, path: s.dir, videos: usedBy((v) => v.series === s.data!.id) })),
    styles: m.styles.map((s) => ({ id: s.id, title: s.title, path: s.path, usedBy: usedBy((v) => v.styles.includes(s.id)) })),
    knowledge: m.knowledge.map((k) => ({ id: k.id, title: k.title, path: k.path })),
    engines: m.engines.map((e) => ({ id: e.id, title: e.title, path: e.path, template: existsSync(join(m.root, 'templates', e.id)) ? `templates/${e.id}` : null, usedBy: usedBy((v) => v.engine === e.id) })),
    packages: m.packages.map((p) => ({ name: p.name, path: p.path, description: p.description, usedBy: usedBy((_v, dir) => importedPackages(m.root, dir).includes(p.name)) })),
    frozen: frozenSources(m),
  });
}

// ---- docs/INDEX.md -------------------------------------------------------------------------

/** front matter `description:` (agent skills and agents), else the first sentence */
function describe(abs: string): string {
  const text = existsSync(abs) ? readFileSync(abs, 'utf8') : '';
  const fm = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text)?.[1];
  const d = fm && /^description:\s*(.+)$/m.exec(fm)?.[1];
  return d ? d.trim().replace(/^["']|["']$/g, '') : mdSummary(abs);
}

const mdFiles = (root: string, dir: string, skip: string[] = []): string[] =>
  existsSync(join(root, dir))
    ? readdirSync(join(root, dir))
        .filter((f) => f.endsWith('.md') && !skip.includes(f))
        .sort()
    : [];

const link = (title: string, to: string) => `[${title}](${to})`;
const fromDocs = (rel: string) => `../${rel}`;
const item = (title: string, rel: string, summary: string, extra = '') => `- ${link(title, fromDocs(rel))}${extra}${summary ? `: ${summary}` : ''}`;

function videoTable(m: RepoModel, rel: (p: string) => string): string[] {
  const videos = videosOf(m);
  if (!videos.length) return ['_No videos yet._'];
  const seriesTitle = new Map(m.series.filter((s) => s.data).map((s) => [s.data!.id, s.data!.title]));
  return [
    '| # | Video | Series | Status | Watch |',
    '|---|---|---|---|---|',
    ...videos.map(({ dir, v }) => {
      const status = v.reproducibility === 'metadata-only' ? `${v.status} (record only)` : v.status;
      const series = v.series ? link(seriesTitle.get(v.series) ?? v.series, rel(`series/${v.series}/SERIES.md`)) : 'standalone';
      return `| ${v.number} | ${link(v.title, rel(`${dir}/README.md`))} | ${series} | ${status} | ${watch(v) ? link('YouTube', watch(v)!) : '—'} |`;
    }),
  ];
}

function indexMd(m: RepoModel): string {
  const r = m.root;
  const L: string[] = [
    '# Index',
    '',
    `<!-- ${GENERATED_NOTE} -->`,
    '',
    'The map of this repository, generated from the files it lists. A session starts here, then',
    'reads [ROADMAP.md](ROADMAP.md) for what is next and [ARCHITECTURE.md](ARCHITECTURE.md) for',
    'where things go. Rules: [CLAUDE.md](../CLAUDE.md). Machine-readable: [catalog.json](../catalog.json).',
    '',
    '## Videos',
    ...videoTable(m, fromDocs),
    '',
    '## Series',
  ];
  for (const s of m.series.filter((x) => x.data)) {
    const n = videosOf(m).filter(({ v }) => v.series === s.data!.id).length;
    L.push(item(s.data!.title, `${s.dir}/SERIES.md`, s.data!.summary, ` (\`${s.data!.id}\`, ${s.data!.status}, ${n} video${n === 1 ? '' : 's'})`));
  }
  L.push('', '## Docs');
  for (const f of ['README.md', 'CLAUDE.md', 'CONTRIBUTING.md', 'NOTICE.md']) if (existsSync(join(r, f))) L.push(item(mdTitle(join(r, f)) ?? f, f, describe(join(r, f))));
  for (const f of mdFiles(r, 'docs', ['INDEX.md'])) L.push(`- ${link(mdTitle(join(r, 'docs', f)) ?? f, f)}${describe(join(r, 'docs', f)) ? `: ${describe(join(r, 'docs', f))}` : ''}`);
  L.push('', '## Engines and templates');
  for (const e of m.engines) {
    const tpl = existsSync(join(r, 'templates', e.id, 'README.md')) ? ` · template ${link(`templates/${e.id}`, fromDocs(`templates/${e.id}/README.md`))}` : '';
    L.push(item(e.title, e.path, e.summary, ` (\`${e.id}\`)${tpl}`));
  }
  if (existsSync(join(r, 'templates/_video'))) L.push(`- ${link('Stage documents', fromDocs('templates/_video/'))}: the stubs \`aiv new\` copies into every video (${mdFiles(r, 'templates/_video').join(', ')})`);
  L.push('', '## Packages');
  for (const p of m.packages) L.push(`- \`${p.name}\` (${link(p.path, fromDocs(p.path))})${p.description ? `: ${p.description}` : ''}`);
  L.push('', '## Styles');
  L.push(...(m.styles.length ? m.styles.map((s) => item(s.title, s.path, s.summary, ` (\`${s.id}\`)`)) : ['_None yet: a style is added when a second video reuses a look ([styles/README.md](../styles/README.md), template [STYLE.md](../styles/_template/STYLE.md))._']));
  L.push('', '## Knowledge');
  L.push(...(m.knowledge.length ? m.knowledge.map((k) => item(k.title, k.path, k.summary)) : ['_None yet._']));
  // the rule of two starts here: what one video built that a second one may need
  const reusable = videosOf(m).flatMap(({ dir, v }) => v.reusable.map((x) => ({ x, dir, slug: v.slug })));
  L.push('', '## Reusable parts of videos');
  L.push(...(reusable.length ? reusable.map(({ x, dir, slug }) => `- ${link(x.what, fromDocs(`${dir}/${x.path}`))} (\`${slug}\`)`) : ['_None declared yet: a video lists parts worth promoting in its `video.json` `reusable`._']));
  L.push('', '## References');
  for (const f of mdFiles(r, 'references', ['README.md'])) L.push(item(mdTitle(join(r, 'references', f)) ?? f, `references/${f}`, describe(join(r, 'references', f))));
  const skills = existsSync(join(r, '.claude/skills'))
    ? readdirSync(join(r, '.claude/skills'))
        .filter((d) => existsSync(join(r, '.claude/skills', d, 'SKILL.md')))
        .sort()
    : [];
  const agents = mdFiles(r, '.claude/agents');
  if (skills.length || agents.length) {
    L.push('', '## Agent skills and agents (Claude Code)');
    for (const d of skills) L.push(item(`skill \`${d}\``, `.claude/skills/${d}/SKILL.md`, describe(join(r, '.claude/skills', d, 'SKILL.md'))));
    for (const f of agents) L.push(item(`agent \`${f.slice(0, -3)}\``, `.claude/agents/${f}`, describe(join(r, '.claude/agents', f))));
  }
  return `${L.join('\n')}\n`;
}

// ---- blocks in hand-written docs -----------------------------------------------------------

/** pnpm-workspace.yaml `catalog:` entries (flat `name: version` lines). */
function catalogPins(root: string): [string, string][] {
  const y = readFileSync(join(root, 'pnpm-workspace.yaml'), 'utf8').replace(/\r\n/g, '\n');
  const start = y.search(/^catalog:\s*$/m);
  if (start < 0) return [];
  const pins: [string, string][] = [];
  for (const line of y.slice(start).split('\n').slice(1)) {
    if (!/^\s/.test(line) && line.trim()) break;
    const m = /^\s+['"]?([^'":#]+?)['"]?\s*:\s*['"]?([^'"#\s]+)['"]?/.exec(line);
    if (m) pins.push([m[1], m[2]]);
  }
  return pins;
}

function versionsTable(root: string): string {
  const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')) as { engines?: { node?: string }; packageManager?: string };
  const rows: [string, string][] = [
    ['node', pkg.engines?.node ?? '?'],
    ['pnpm', pkg.packageManager?.replace(/^pnpm@/, '') ?? '?'],
    ...catalogPins(root),
  ];
  return ['| Tool or package | Version |', '|---|---|', ...rows.map(([n, v]) => `| \`${n}\` | ${v} |`)].join('\n');
}

// ---- all of them ---------------------------------------------------------------------------

export function generatedFiles(m: RepoModel): Generated[] {
  return [
    ...SCHEMAS.map((s) => ({ path: s.file, content: schemaFile(s) })),
    { path: 'catalog.json', content: catalog(m) },
    { path: 'docs/INDEX.md', content: indexMd(m) },
    { path: 'README.md', block: 'catalog', content: videoTable(m, (p) => p).join('\n') },
    { path: 'docs/PRODUCTION.md', block: 'gates', content: gatesTable() },
    { path: 'docs/ENVIRONMENT.md', block: 'versions', content: versionsTable(m.root) },
    { path: 'tsconfig.json', jsonField: 'exclude', content: JSON.stringify(frozenSources(m)) },
  ];
}

const blockRe = (name: string) => new RegExp(`(<!-- aiv:generated ${name} -->)[\\s\\S]*?(<!-- /aiv:generated -->)`);

/** The file's text with the generated part in place, or null when the block marker is missing. */
export function render(g: Generated, current: string | null): string | null {
  if (g.jsonField) {
    let obj: Record<string, unknown>;
    try {
      obj = JSON.parse(current ?? '{}') as Record<string, unknown>;
    } catch (e) {
      throw new Error(`${g.path} must stay plain JSON (no comments): aiv check --fix rewrites its '${g.jsonField}' list. ${(e as Error).message}`, { cause: e });
    }
    const value = JSON.parse(g.content) as unknown[];
    if (value.length) obj[g.jsonField] = value;
    else delete obj[g.jsonField];
    return json(obj);
  }
  if (!g.block) return g.content;
  if (current === null || !blockRe(g.block).test(current)) return null;
  return current.replace(blockRe(g.block), (_all, open: string, close: string) => `${open}\n${g.content}\n${close}`);
}

export function freshness(root: string, g: Generated): { state: Freshness; expected: string | null } {
  const abs = join(root, g.path);
  const current = existsSync(abs) ? readFileSync(abs, 'utf8').replace(/\r\n/g, '\n') : null;
  const expected = render(g, current);
  if (expected === null) return { state: 'no-marker', expected };
  return { state: expected === current ? 'fresh' : 'stale', expected };
}
